import json
def _unique(pairs):
    result = {}
    for key,value in pairs:
        if key in result:
            raise ValueError('duplicate key: ' + key)
        result[key] = value
    return result

def load_config(text):
    value = json.loads(text,object_pairs_hook=_unique)
    if not isinstance(value,dict):
        raise ValueError('configuration must be an object')
    return value

