class History:
    def __init__(self,initial):
        self.entries=[initial]
        self.index=0
    @property
    def value(self):
        return self.entries[self.index]
    def push(self,value):
        self.entries=self.entries[:self.index+1]+[value]
        self.index+=1
    def undo(self):
        if self.index>0:
            self.index-=1
    def redo(self):
        if self.index<len(self.entries)-1:
            self.index+=1
